OWW={}; OWW.f=CreateFrame("Frame","OWWATCH",UIParent); OWW.last=GameTooltip:IsShown(); OWW.f:SetScript("OnUpdate",function() local s=GameTooltip:IsShown(); if s~=OWW.last then OWW.last=s; local m=GetMouseFocus and GetMouseFocus() or nil; local n="?"; if m then n=tostring(m.GetName and m:GetName() or m) end; DEFAULT_CHAT_FRAME:AddMessage("GT"..(s and "+" or "-")..string.format(" t=%.2f",GetTime()).." focus="..n) end end); DEFAULT_CHAT_FRAME:AddMessage("OWWATCH-INSTALLED")